1	package registry
2	
3	import "fmt"
4	
5	// 直接转让（Transfer 与 TransferBatch）共用的资格规则。
6	//
7	// 一件藏品只有在以下条件全部成立时才能直接转让：
8	//   - 藏品及其持有记录存在；
9	//   - 操作者（当前持有人）账户已登记且可用；
10	//   - 接收账户已登记、可用，且与当前持有人不同；
11	//   - 期望持有人、期望版本与当前持有一致，且操作者就是当前持有人。
12	//
13	// 系列封存不妨碍已发行藏品转让，因此这里不检查封存状态。规则的每一步
14	// 都由两个入口按各自的顺序编排：单件转让按"藏品 → 操作者 → 接收人 →
15	// 收发同人 → 持有信息"的顺序；整批先查操作者，再逐件按"藏品 → 接收人
16	// → 收发同人 → 持有信息"的顺序。参数合法性（必填内容、正期望版本、
17	// 非负价款）仍由两个入口各自的 validatePresent 在进入资格检查前完成；
18	// 代转授权不使用这里的规则，沿用 ProxyTransfer 原有行为。
19	
20	// directTransferEligibility 汇集一件藏品直接转让资格判断所需的全部输入，
21	// 与具体入口无关。
22	type directTransferEligibility struct {
23		itemID        string // 藏品编号
24		operator      string // 操作者，必须是当前持有人
25		toID          string // 接收账户
26		expectedOwner string // 期望当前持有人
27		expectedVer   int64  // 期望当前持有版本
28	}
29	
30	// itemTransferEligibility 判断藏品与持有记录是否存在。
31	// 单件与整批都在账户问题之前先判断各自引用的藏品；持有记录缺失同样按
32	// 对象不存在处理。
33	func (r *Registry) itemTransferEligibility(itemID string) error {
34		if _, ok := r.state.Holdings[itemID]; !ok {
35			if _, itemExists := r.state.Items[itemID]; !itemExists {
36				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
37			}
38			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, itemID)
39		}
40		return nil
41	}
42	
43	// operatorTransferEligibility 判断操作者账户是否已登记且可用。
44	func (r *Registry) operatorTransferEligibility(operator string) error {
45		op, ok := r.state.Accounts[operator]
46		if !ok {
47			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, operator)
48		}
49		if !op.Active {
50			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, operator)
51		}
52		return nil
53	}
54	
55	// recipientTransferEligibility 判断接收账户是否已登记且可用。两个入口的
56	// 拒绝信息相同；整批由编排层另行在结果中关联藏品编号。
57	func (r *Registry) recipientTransferEligibility(toID string) error {
58		to, ok := r.state.Accounts[toID]
59		if !ok {
60			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, toID)
61		}
62		if !to.Active {
63			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, toID)
64		}
65		return nil
66	}
67	
68	// sameHolderEligibility 判断接收人是否就是当前持有人。两个入口共用
69	// ErrSameAccount；整批的错误信息指出藏品编号。
70	func sameHolderEligibility(toID, ownerID, itemID string, withItem bool) error {
71		if toID != ownerID {
72			return nil
73		}
74		if withItem {
75			return fmt.Errorf("%w: 接收人 %s 已是藏品 %s 的当前持有人",
76				ErrSameAccount, toID, itemID)
77		}
78		return fmt.Errorf("%w: 接收人 %s 已是当前持有人", ErrSameAccount, toID)
79	}
80	
81	// holdingTransferEligibility 判断期望持有人、期望版本与当前持有是否一致，
82	// 以及操作者是否就是当前持有人。两个入口的拒绝信息相同；系列封存不阻止
83	// 转让，这里不检查封存状态。
84	func holdingTransferEligibility(q directTransferEligibility, ownerID string, ownerVer int64) error {
85		if ownerID == q.expectedOwner && ownerVer == q.expectedVer && q.operator == ownerID {
86			return nil
87		}
88		return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
89			ErrConflict, q.itemID, ownerID, ownerVer)
90	}
91	
92	// checkSingleTransferEligibility 按单件转让的优先级编排共用规则：
93	// 藏品及持有记录不存在优先于账户问题；操作者的登记和停用问题优先于
94	// 接收账户问题；接收账户问题优先于收发同人；收发同人又优先于持有信息
95	// 不符。例如操作者停用而藏品不存在时仍返回对象不存在；接收人就是当前
96	// 持有人且期望版本填错时，仍先返回收发同人。
97	func (r *Registry) checkSingleTransferEligibility(q directTransferEligibility) error {
98		if err := r.itemTransferEligibility(q.itemID); err != nil {
99			return err
100		}
101		if err := r.operatorTransferEligibility(q.operator); err != nil {
102			return err
103		}
104		if err := r.recipientTransferEligibility(q.toID); err != nil {
105			return err
106		}
107		h := r.state.Holdings[q.itemID]
108		if err := sameHolderEligibility(q.toID, h.OwnerID, q.itemID, false); err != nil {
109			return err
110		}
111		return holdingTransferEligibility(q, h.OwnerID, h.Version)
112	}
113	
114	// checkBatchTransferEligibility 按整批转让的优先级编排共用规则：操作者
115	// 未登记或停用最先报告且不关联任何藏品（itemID 返回空）；操作者可用后，
116	// 按清单顺序逐件检查，只指出第一件失败的藏品与原因——藏品不存在先于
117	// 该件接收账户问题，接收账户问题先于收发同人，收发同人先于持有信息
118	// 不符，后面条目的错误不会提前。
119	func (r *Registry) checkBatchTransferEligibility(operator string, entries []TransferBatchEntry) (string, error) {
120		if err := r.operatorTransferEligibility(operator); err != nil {
121			return "", err
122		}
123		for _, e := range entries {
124			q := directTransferEligibility{
125				itemID: e.ItemID, operator: operator, toID: e.ToID,
126				expectedOwner: e.ExpectedOwner, expectedVer: e.ExpectedVer,
127			}
128			if err := r.itemTransferEligibility(e.ItemID); err != nil {
129				return e.ItemID, err
130			}
131			if err := r.recipientTransferEligibility(e.ToID); err != nil {
132				return e.ItemID, err
133			}
134			h := r.state.Holdings[e.ItemID]
135			if err := sameHolderEligibility(e.ToID, h.OwnerID, e.ItemID, true); err != nil {
136				return e.ItemID, err
137			}
138			if err := holdingTransferEligibility(q, h.OwnerID, h.Version); err != nil {
139				return e.ItemID, err
140			}
141		}
142		return "", nil
143	}
144

