17	// TestSingleTransferEligibilityPrecedence 覆盖单件转让的优先级组合。
18	func TestSingleTransferEligibilityPrecedence(t *testing.T) {
19		r := mustCreate(t, tempDir(t))
20		setupWorld(t, r) // alice、bob 可用，系列 s1
21		r.RegisterAccount("carol", "")
22		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
23			t.Fatal(err)
