	if res.ItemID != "taken" {
		t.Fatalf("single-issue rejection must carry request ItemID, got %q", res.ItemID)
	}

	// 操作者停用且系列已封存：仍先报操作者停用。
	r2 := mustCreate(t, tempDir(t))
