		t.Fatal(err)
	}
	if _, err := r2.Issue(issueReq("i1", "bob")); !errors.Is(err, ErrAccountInactive) {
		t.Fatalf("inactive operator must outrank sealed series, got %v", err)
	}

	// 操作者可用但不是创建账户，且系列已封存：封存优先于非创建账户。
	r3 := mustCreate(t, tempDir(t))
